mapper.select:
SELECT
    id, tenant_code, user_code, flow_no, consume_time, points, reason, order_no, status,
    sort, create_time, create_by, update_time, update_by, remark, version
FROM
    points_consume_record
WHERE
    deleted = 0
    AND tenant_code = #{tenantCode}
    AND user_code = #{userCode}

        AND consume_time >= #{startTime}


        AND consume_time <= #{endTime}

ORDER BY consume_time DESC, id DESC
